def __init__(
    self, hap: HomematicipHAP, device, channel: int, post: str | None = None
) -> None:
    """Initialize the notification light entity."""
    if post is None:
        post = "Top" if channel == 2 else "Bottom"

    super().__init__(
        hap, device, post=post, channel=channel, is_multi_channel=True
    )
